  this.indexedFiles=initialFiles;this.notes=notes.sort((a,b)=>a.path.localeCompare(b.path,'zh-CN',{numeric:true})||(a.path<b.path?-1:a.path>b.path?1:0));this.scanWarnings=warnings;this.loading=false;this.scanProgress.milliseconds=Math.round(performance.now()-started);
  const valid=new Set(this.notes.flatMap(n=>n.knowledge||[]).map(p=>p.id));for(const id of this.selectedCandidates.keys())if(!valid.has(id))this.selectedCandidates.delete(id);
