 private beginOutline(branch:OutlineBranch){this.outline=branch;this.outlineRevealed=0;this.outlineRecall='';this.screen='outline';this.host.shield(this.visible());this.saveLocation('outline',branch);this.render();this.focusRecall();}
 private renderOutline(root:HTMLElement){
  const branch=this.outline!,complete=this.outlineRevealed>=branch.children.length;
  root.createEl('p',{text:branch.path,cls:'pp-source-path'});if(branch.ancestorPath.length)root.createEl('p',{text:branch.ancestorPath.join(' › '),cls:'pp-heading-path'});
  root.createEl('h2',{text:'它有哪些子分支？',cls:'pp-stage-title'});const parent=root.createDiv({cls:'pp-outline-parent'});parent.createEl('span',{text:'父节点 · 本轮提示',cls:'pp-face-label'});parent.createEl('p',{text:branch.label,cls:'pp-question'});
  root.createEl('p',{text:`已揭晓 ${Math.min(this.outlineRevealed,branch.children.length)} / ${branch.children.length} 个直属子节点`,cls:'pp-progress',attr:{role:'status'}});
  if(!complete)this.field(root,'我记得的分支（可选）',this.outlineRecall,value=>this.outlineRecall=value,'可以只写关键词，每行一个……');else if(this.outlineRecall){const recall=root.createDiv({cls:'pp-reading'});recall.createEl('span',{text:'我的回忆',cls:'pp-face-label'});this.previews.mount(recall,this.outlineRecall,branch.path);}
  const tree=root.createEl('ol',{cls:'pp-outline-tree','attr':{'aria-label':'本轮子分支'}});
  branch.children.forEach((node,index)=>{const item=tree.createEl('li',{cls:index<this.outlineRevealed?'is-revealed':'is-hidden'});
   if(index>=this.outlineRevealed){item.createEl('span',{text:'尚未揭晓',cls:'pp-outline-placeholder'});return;}
   item.createEl('span',{text:node.label,cls:'pp-outline-node'});
   if(node.children.length){const child:OutlineBranch={id:node.id,label:node.label,line:node.line,path:node.path,headingPath:node.kind==='heading'?[...branch.headingPath,node.label]:[...branch.headingPath],ancestorPath:[...branch.ancestorPath,node.label],children:node.children};this.button(item,`继续回忆下一级（${node.children.length}）`,()=>{if(this.outline!==branch)return;this.outlineHistory.push(branch);this.beginOutline(child);});}
  });
  const actions=root.createDiv({cls:'pp-actions'});
  if(!complete){this.button(actions,'揭晓下一个分支',()=>{if(this.outline!==branch)return;this.outlineRevealed++;this.host.shield(this.outlineRevealed<branch.children.length&&this.visible());this.render();},true);this.button(actions,'全部揭晓',()=>{if(this.outline!==branch)return;this.outlineRevealed=branch.children.length;this.host.shield(false);this.render();});}
  else this.button(actions,'重新回忆本节点',()=>{if(this.outline===branch)this.beginOutline(branch);},true);
  if(this.outlineHistory.length)this.button(actions,'返回上一级节点',()=>{if(this.outline===branch)this.beginOutline(this.outlineHistory.pop()!);});
  if(complete&&this.outlineQueue.length>this.outlinePosition+1)this.button(actions,'下一分支题',()=>{if(this.outline!==branch)return;this.outlinePosition++;this.outlineHistory=[];this.beginOutline(this.outlineQueue[this.outlinePosition]);});
  root.createEl('p',{text:complete?'核对后可继续深入下一层。':'先回想，再逐项揭晓。',cls:'pp-footnote'});
 }
 private startCards(cards:Card[]){this.againCandidates.clear();this.repeatPass=false;this.queue=sessionOrder(cards,this.reviewOrder);this.reviewed=0;this.sessionTotal=cards.length;this.undo=undefined;this.screen='card';this.advance();}
