  if((this.host.store?.schedulingAlgorithm??'fsrs')==='sm2-osr')root.createEl('p',{text:'按天复习 · 忘了会在今天到期，本轮结束后可再练',cls:'pp-footnote'});if(activeAlgorithm(c)!==(this.host.store?.schedulingAlgorithm??'fsrs'))root.createEl('p',{text:'本次评分将初始化所选算法，之前的复习历史保留',cls:'pp-footnote'});
  root.createEl('p',{text:c.sourcePath||'本地快照 · 无来源笔记',cls:'pp-source-path'});if(c.id.startsWith('note:')&&!this.notes.some(n=>n.cards.some(x=>x.id===c.id)))root.createEl('p',{text:'来源标记缺失：本次使用已保存的最后快照，评分继续独立保存。',cls:'pp-footnote'});const front=root.createDiv({cls:'pp-front'});front.createEl('span',{text:'正面 · 问题',cls:'pp-face-label'});this.previews.mount(front,c.front,c.sourcePath);
