 private assertIndexCurrent(indexedFiles:readonly {file:TFile;path:string;mtime:number;size:number}[],exclusions:readonly string[]){const files=this.app.vault.getMarkdownFiles().filter(f=>!excluded(f.path,['Passage Practice','Passage Practice backups',...exclusions])),set=new Set(files);if(files.length!==indexedFiles.length||indexedFiles.some(x=>!set.has(x.file)||x.file.path!==x.path||x.file.stat.mtime!==x.mtime||x.file.stat.size!==x.size))throw new Error('评分提交前笔记已变化，请刷新后重新复习');}
 private async rate(c:Card,rating:Rating){const before={queue:[...this.queue],reviewed:this.reviewed,total:this.sessionTotal,again:[...this.againCandidates],repeatPass:this.repeatPass};await this.run(async()=>{if(c.id.startsWith('note:')){if(!await this.refresh())throw new Error('内容刷新被中断，本次未评分，请返回后重新开始');const current=studyCards(this.notes,this.host.store!.cards,{kind:'all',value:''},'',Date.now()).cards.find(x=>x.id===c.id);if(!current||current.front!==c.front||current.back!==c.back||current.revision!==c.revision)throw new Error('来源卡片已修改、移除或编号重复。本次未评分，请返回学习并重新开始。');const verifiedFiles=this.indexedFiles.map(x=>({...x})),exclusions=[...this.excludedPaths];return this.host.store!.rateAuthored({...c,sourcePath:current.sourcePath},rating,Date.now(),()=>this.assertIndexCurrent(verifiedFiles,exclusions));}return this.host.store!.rate(c.id,c.revision,rating);},()=>{if(rating==='again'&&!this.repeatPass)this.againCandidates.add(c.id);else this.againCandidates.delete(c.id);this.undo={previous:c,revision:c.revision+1,...before};this.queue.shift();this.reviewed++;this.advance();});}
