 openSeed(seed:CardSeed){if(this.screen!=='home'){new Notice('请先返回学习，再创建新卡片');return;}this.mode='cards';this.openEditor(undefined,false,seed);}
 private openEditor(card?:Card,insert=false,seed?:CardSeed){if(!this.host.store){new Notice(this.host.storageError);return;}this.returnScreen=this.screen==='library'?'library':this.screen==='card'?'card':this.screen==='passage'?'passage':'home';this.draft=seed?{...seed}:card?{front:card.front,back:card.back,sourcePath:card.sourcePath,sourceRef:card.sourceRef}:{front:'',back:'',sourcePath:''};this.editCard=card;this.clozeTerm='';this.relearn=false;this.insert=false;this.screen='edit';this.render();}
