  const selectedDeck=this.host.store?.decks.find(d=>d.id===this.selectedDeck);if(selectedDeck)this.button(membership,'从当前卡组移出所选卡片',()=>{const selected=[...this.selectedCards.values()];if(!selected.length){this.message='请先选择卡片';this.render();return;}void this.run(()=>this.host.store!.removeFromDeck(selectedDeck.id,selectedDeck.revision,selected),()=>{this.selectedCards.clear();this.message='已移出当前卡组；卡片和评分保留，可在全部卡组中重新加入';});});
