  const leaves=this.app.workspace.getLeavesOfType('markdown').filter(leaf=>leaf.view.containerEl.closest('.mod-root'));
  const leaf=leaves.find(l=>(l.view as MarkdownView).file?.path===path)||leaves.find(l=>(l.view as MarkdownView).file?.path===this.host.currentPath)||leaves[0]||this.app.workspace.getLeaf('tab');
  if(!current())return;await leaf.openFile(file,{active:true,eState:{line}});
